python.solution:
def count_words(words: list[str]) -> dict[str, int]:
    counts: dict[str, int] = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts


words = input().split()
counts = count_words(words)
for word in sorted(counts):
    print(word, counts[word])

